@extends('layouts.app') @section('title',$category->exists?'Edit Category':'Add Category') @section('content')<x-errors/><form class="card p-4" method="post" action="{{$category->exists?route('categories.update',$category):route('categories.store')}}">@csrf @if($category->exists)@method('put')@endif<div class="mb-3"><label class="form-label">Category Name *</label><input class="form-control" name="name" value="{{old('name',$category->name)}}" required></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description">{{old('description',$category->description)}}</textarea></div><div class="mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" @selected(old('status',$category->status??'active')==='active')>Active</option><option value="inactive" @selected(old('status',$category->status)==='inactive')>Inactive</option></select></div><div><button class="btn btn-primary">Save Category</button><a class="btn btn-light" href="{{route('categories.index')}}">Cancel</a></div></form>@endsection
